   443→      } else if (line.isNumericTag()) {
   444→        if (line.isControlField()) {
   445→          marc4jRecord.addVariableField(new ControlFieldImpl(line.getTag(), line.getContent()));
   446→        } else {
   447→          var df = new DataFieldImpl(line.getTag(), line.getInd1().charAt(0), line.getInd2().charAt(0));
   448→          for (String[] pair : line.parseSubfields()) {
   449→            if (pair.length == 2 && pair[0] != null && pair[1] != null) {
   450→              df.addSubfield(new SubfieldImpl(pair[0].charAt(0), pair[1]));
   451→            } else {
   452→              logger.warning(String.format(
